css:
#loader-35 {
  width: 18px;
  aspect-ratio: 1;
  background: #3FB8AF;
  animation:
    l7-1 1s infinite alternate,
    l7-2 2s infinite alternate;
}
@keyframes l7-1 {
   0%,10%{transform:scale(1) rotate(0)}
   100%  {transform:scale(0) rotate(1turn)}
}
@keyframes l7-2 {
   0%,49.99% {background:#3FB8AF}
   50%,100%  {background:#FF3D7F}
}
